// THROWAWAY: three alternatives for source icons and placement. All state stays in memory.

(() => {
 const root=document.getElementById('sbs-status-prototype');
 const examples=[{title:'Setenta y cuatro',learning:'Am Üben',tags:'',time:'0:52',videos:1,state:'cloud'},{title:'Italiana',learning:'Am Üben',tags:'',time:'1:09',videos:2,state:'local'},{title:'Cross Body mit Drehung',learning:'Neu',tags:'Salsa · Kombination',time:'1:08',videos:1,state:'modified'}];
 const icon=name=>`<i data-lucide="${name}" aria-hidden="true"></i>`;
 const sourceIcon=state=>state==='local'?icon('smartphone'):state==='cloud'?icon('cloud'):`<span class="sbs-compound">${icon('cloud')}${icon('pencil')}</span>`;
 const label={local:'Nur lokal',cloud:'Cloud',modified:'Lokal angepasst'};
 const explanation={local:'Diese Figur ist nur auf diesem Gerät gespeichert.',cloud:'Diese Figur wurde aus der Cloud übernommen oder von dir dort gespeichert.',modified:'Diese Figur stammt aus der Cloud. Titel, Beschreibung, Tags oder Videos wurden danach lokal angepasst. Dein Lernstatus zählt nicht als Anpassung.'};
 const source=(f,extra='')=>`<button type="button" class="sbs-source cursor-interaction ${extra}" data-source="${f.state}" data-details="${f.state}" aria-label="${label[f.state]} – Details anzeigen">${sourceIcon(f.state)}${extra?'':`<span>${label[f.state]}</span>`}</button>`;
 for(const stage of root.querySelectorAll('[data-variant]')){
  const layout=stage.dataset.layout,phone=stage.querySelector('.sbs-phone');
  phone.innerHTML=`<div class="sbs-shell"><header class="sbs-brand"><span class="sbs-mark" aria-hidden="true"></span><div><b>Step by Step</b><span class="sbs-tagline">Deine Schritte. Dein Tempo.</span></div><button type="button" class="sbs-settings cursor-interaction" aria-label="Einstellungen">${icon('settings')}</button></header><div class="sbs-heading"><h2>Meine Figuren</h2><button type="button" class="sbs-add cursor-interaction" aria-label="Figur hinzufügen">${icon('plus')}</button></div><label class="sbs-search">${icon('search')}<input type="search" placeholder="Figur suchen" aria-label="Figur suchen"></label><div class="sbs-filters" aria-label="Lernstand filtern">${['Alle','Neu','Am Üben','Sitzt'].map((v,i)=>`<button type="button" class="cursor-interaction" aria-pressed="${i===0}" data-filter="${v}">${v}</button>`).join('')}</div><div class="sbs-count"><span data-count>3 Figuren</span><span>Sortierung: Neueste</span></div></div><div class="sbs-list">${examples.map(f=>`<article class="sbs-card" data-learning="${f.learning}" data-title="${f.title.toLowerCase()}"><div class="sbs-main"><div class="sbs-thumb-wrap"><div class="sbs-thumb" aria-hidden="true">${icon('circle-play')}</div>${layout==='picture'?source(f,'sbs-picture-badge'):''}</div><div class="sbs-copy"><button type="button" class="sbs-title cursor-interaction" data-preview="${f.title}">${f.title}</button><span class="sbs-learning" data-learning="${f.learning}">${f.learning}</span>${f.tags?`<div class="sbs-tags">${f.tags}</div>`:''}<span class="sbs-meta">Geräteordner · Documents</span>${layout==='meta'?`<div class="sbs-inline-meta"><span>${f.time} · ${f.videos} Video${f.videos===1?'':'s'}</span><span aria-hidden="true">·</span>${source(f)}</div>`:layout==='picture'?`<span class="sbs-meta">${f.time} · ${f.videos} Video${f.videos===1?'':'s'}</span>`:''}</div><button type="button" class="sbs-menu cursor-interaction" aria-label="Optionen für ${f.title}" data-preview="${f.title}">${icon('ellipsis-vertical')}</button></div>${layout==='strip'?`<div class="sbs-status-row">${source(f)}<span class="sbs-meta">${f.time} · ${f.videos} Video${f.videos===1?'':'s'}</span></div>`:''}</article>`).join('')}</div><nav class="sbs-nav" aria-label="Hauptnavigation"><button type="button" aria-current="page" class="cursor-interaction"><span class="sbs-mark" aria-hidden="true"></span>Figuren</button><button type="button" class="cursor-interaction" data-cloud>${icon('cloud')}Cloud-Speicher</button></nav><section class="sbs-sheet" aria-live="polite" hidden><button type="button" data-close class="cursor-interaction" aria-label="Schließen">${icon('x')}</button><h3></h3><p></p></section>`;
  const sheet=phone.querySelector('.sbs-sheet');
  const show=(heading,message)=>{sheet.querySelector('h3').textContent=heading;sheet.querySelector('p').textContent=message;sheet.hidden=false;};
  phone.addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;if(button.hasAttribute('data-details'))show(label[button.dataset.details],explanation[button.dataset.details]);else if(button.hasAttribute('data-close'))sheet.hidden=true;else if(button.hasAttribute('data-preview'))show(button.dataset.preview,'Vorschau im Prototyp. Deine gespeicherten Figuren bleiben unverändert.');else if(button.hasAttribute('data-cloud'))show('Cloud-Speicher','Hier würdest du deine Cloudfiguren und Bibliotheken öffnen.');else if(button.classList.contains('sbs-add'))show('Figur hinzufügen','Im Prototyp sind drei Beispiel-Figuren vorbereitet.');else if(button.classList.contains('sbs-settings'))show('Einstellungen','Dies ist eine Vorschau der Figurenübersicht.');});
  let selected='Alle';const filter=()=>{const query=phone.querySelector('input').value.trim().toLowerCase();let count=0;phone.querySelectorAll('.sbs-card').forEach(card=>{card.hidden=(selected!=='Alle'&&card.dataset.learning!==selected)||!card.dataset.title.includes(query);if(!card.hidden)count++;});phone.querySelector('[data-count]').textContent=`${count} Figuren`;};
  phone.querySelector('input').addEventListener('input',filter);
  phone.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{selected=button.dataset.filter;phone.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));filter();}));
 }
 if(window.lucide)lucide.createIcons({attrs:{width:18,height:18}});
})();
